/* Only real credited events create the mint return stream. Forward damage is purple. */
static int renderedSiphonReturns84;
static void siphon_stream84(float x,float y,float xx,float yy,float width,float intensity){beam_ribbon(x,y,xx,yy,width*2.2f,(SDL_FColor){.42f,.12f,.8f,.12f*intensity});beam_ribbon(x,y,xx,yy,width*.75f,(SDL_FColor){.62f,.28f,1,.48f*intensity});beam_ribbon(x,y,xx,yy,fmaxf(.24f,width*.16f),(SDL_FColor){.91f,.8f,1,.88f*intensity});light(xx,yy,width+3,.65f,.28f,1,.22f*intensity);}
static void siphon_disabled_marker84(float x,float y,float radius,float strength){radius=fmaxf(radius,6/fmaxf(.32f,journeyZoom));for(int side=-1;side<=1;side+=2){beam_ribbon(x+side*radius,y-radius*.65f,x+side*radius,y+radius*.65f,.35f,(SDL_FColor){.75f,.4f,1,.8f*strength});beam_ribbon(x+side*radius,y-radius*.65f,x+side*(radius-3),y-radius*.65f,.35f,(SDL_FColor){.8f,.55f,1,.8f*strength});}beam_ribbon(x-radius*.3f,y-radius*.35f,x+radius*.3f,y+radius*.35f,.45f,(SDL_FColor){.85f,.5f,1,.8f*strength});}
static void draw_siphon84(void){renderedSiphonReturns84=0;if(g.mode!=1||ex.travel||ex.intro)return;for(int i=0;i<MAXE;i++){Obj*o=g.enemies+i;if(o->on&&o->siphon84.disarm)siphon_disabled_marker84(o->x/(float)Q,o->y/(float)Q,pc_enemy_radius(o)+3,fminf(1,o->siphon84.disarm/5.f));}for(int i=0;i<32;i++){EnvironmentHazard*h=ex.env.hazards+i;if(h->on&&h->siphon84.disarm)siphon_disabled_marker84(h->x/(float)Q,h->y/(float)Q,h->r+3,fminf(1,h->siphon84.disarm/5.f));}Giant*b=&ex.giant;if(b->active&&b->siphon84.disarm)siphon_disabled_marker84(b->parts[6].x,b->parts[6].y,fmaxf(b->parts[6].w,b->parts[6].h)*.6f,fminf(1,b->siphon84.disarm/5.f));int limit=reducedMotion?12:64;for(int i=0;i<64&&renderedSiphonReturns84<limit;i++){SiphonReturn84*p=siphonReturns84+i;float t=(g.tick-p->tick)/18.f,x,y;if(!siphon_return_point84(p,t,&x,&y))continue;float size=.8f/fmaxf(.32f,journeyZoom),alpha=.8f*(1-t);if(reducedMotion){x=g.px/(float)Q;y=player_y/(float)Q;size*=2;alpha=.16f*(1-t);}else{float xx,yy;if(siphon_return_point84(p,fmaxf(0,t-.1f),&xx,&yy))beam_ribbon(xx,yy,x,y,.2f,(SDL_FColor){.3f,1,.8f,alpha*.5f});}light(x,y,size,.55f,1,.82f,alpha);renderedSiphonReturns84++;}}
